import hashlib

def compute_kafka_key(tenant_id: str, trace_id: str, tenant_shards: int = 8) -> bytes:
    digest = hashlib.blake2b(trace_id.encode('utf-8'), digest_size=4).digest()
    shard = int.from_bytes(digest, 'big') % tenant_shards
    return f"{tenant_id}:{shard}".encode('utf-8')

ALLOWED_KEYS = {'ts', 'tenant_id', 'service', 'level', 'trace_id', 'message'}
MAX_ATTR_KEYS = 32

def normalize_log(raw: dict) -> dict:
    attrs = {}
    for k, v in raw.items():
        if k not in ALLOWED_KEYS and len(attrs) < MAX_ATTR_KEYS:
            attrs[str(k)[:64]] = str(v)[:512]
    return {
        'ts': raw['ts'],
        'tenant_id': raw.get('tenant_id', 'unknown'),
        'service': raw.get('service', 'unknown'),
        'level': raw.get('level', 'INFO'),
        'trace_id': raw.get('trace_id', ''),
        'message': str(raw.get('message', ''))[:8192],
        'attributes': attrs,
    }
